import React, { useEffect, useState } from "react";
import { Plus, Trash2, MessageSquare } from "lucide-react";
import api from "../services/api";

export default function Grievances() {
    const [data, setData] = useState([]);
    const [open, setOpen] = useState(false);
    const [msg, setMsg] = useState("");
    const [error, setError] = useState("");

    const [form, setForm] = useState({
        memberName: "",
        category: "Payment",
        subject: "",
        priority: "Medium",
        description: ""
    });

    // =========================
    // LOAD GRIEVANCES
    // =========================
    const load = async () => {
        try {
            const response = await api.get("/grievances");

            console.log("GRIEVANCES API RESPONSE:", response.data);

            setData(response.data);
        } catch (err) {
            console.error("GRIEVANCES LOAD ERROR:", err);

            // Don't show error when there are simply no records
            setData([]);
        }
    };

    useEffect(() => {
        load();
    }, []);

    // =========================
    // HANDLE INPUT
    // =========================
    const handleChange = (e) => {
        const { name, value } = e.target;

        setForm((prev) => ({
            ...prev,
            [name]: value
        }));
    };

    // =========================
    // SUBMIT GRIEVANCE
    // =========================
    const submit = async (e) => {
        e.preventDefault();

        setMsg("");
        setError("");

        console.log("GRIEVANCE FORM:", form);

        try {
            const response = await api.post("/grievances", {
                memberName: form.memberName.trim(),
                category: form.category,
                subject: form.subject.trim(),
                priority: form.priority,
                description: form.description.trim()
            });

            console.log(
                "GRIEVANCE POST RESPONSE:",
                response.data
            );

            setMsg("Grievance submitted successfully.");

            setForm({
                memberName: "",
                category: "Payment",
                subject: "",
                priority: "Medium",
                description: ""
            });

            setOpen(false);

            await load();

        } catch (err) {
            console.error(
                "GRIEVANCE SUBMIT ERROR:",
                err
            );

            console.error(
                "STATUS:",
                err.response?.status
            );

            console.error(
                "BACKEND RESPONSE:",
                err.response?.data
            );

            // Show the REAL backend error
            if (err.response?.data?.message) {
                setError(
                    `Error ${err.response.status}: ${err.response.data.message}`
                );
            } else if (err.response?.data?.errors) {
                setError(
                    `Error ${err.response.status}: ${JSON.stringify(
                        err.response.data.errors
                    )}`
                );
            } else if (err.response?.status) {
                setError(
                    `Error ${err.response.status}: Unable to submit grievance.`
                );
            } else {
                setError(
                    "Unable to connect to the backend server."
                );
            }
        }
    };

    // =========================
    // DELETE
    // =========================
    const deleteGrievance = async (id) => {
        try {
            await api.delete(`/grievances/${id}`);

            setMsg("Grievance deleted successfully.");

            await load();

        } catch (err) {
            console.error(
                "DELETE GRIEVANCE ERROR:",
                err
            );

            setError(
                err.response?.data?.message ||
                "Unable to delete grievance."
            );
        }
    };

    return (
        <>
            {/* HEADER */}
            <div className="page-head">

                <div>

          <span className="eyebrow">
            FARMER SUPPORT
          </span>

                    <h2>
                        Grievances & Feedback
                    </h2>

                    <p>
                        Submit and manage farmer complaints,
                        issues and feedback.
                    </p>

                </div>

                <button
                    className="primary"
                    onClick={() => {
                        setOpen(true);
                        setMsg("");
                        setError("");
                    }}
                >
                    <Plus size={17} />
                    Add grievance
                </button>

            </div>

            {/* SUCCESS */}
            {msg && (
                <div className="alert success-alert">
                    {msg}
                </div>
            )}

            {/* ERROR */}
            {error && (
                <div className="alert">
                    {error}
                </div>
            )}

            {/* LIST */}
            <div className="panel">

                <div className="panel-head">

                    <div>

                        <h3>
                            Grievance Records
                        </h3>

                        <p>
                            View submitted farmer complaints
                            and feedback.
                        </p>

                    </div>

                </div>

                {data.length > 0 ? (

                    <div className="table-wrap">

                        <table>

                            <thead>

                            <tr>
                                <th>Member</th>
                                <th>Category</th>
                                <th>Subject</th>
                                <th>Priority</th>
                                <th>Status</th>
                                <th>Date</th>
                                <th>Action</th>
                            </tr>

                            </thead>

                            <tbody>

                            {data.map((g) => (

                                <tr key={g.id}>

                                    <td>
                                        <b>
                                            {g.memberName || "-"}
                                        </b>
                                    </td>

                                    <td>
                                        {g.category || "-"}
                                    </td>

                                    <td>
                                        {g.subject || "-"}
                                    </td>

                                    <td>
                      <span className="badge warning">
                        {g.priority || "Medium"}
                      </span>
                                    </td>

                                    <td>
                      <span className="badge pending">
                        {g.status || "OPEN"}
                      </span>
                                    </td>

                                    <td>
                                        {g.createdAt
                                            ? String(g.createdAt)
                                                .replace("T", " ")
                                                .substring(0, 16)
                                            : "-"}
                                    </td>

                                    <td>

                                        <button
                                            className="small-btn danger-btn"
                                            onClick={() =>
                                                deleteGrievance(g.id)
                                            }
                                        >
                                            <Trash2 size={15} />
                                        </button>

                                    </td>

                                </tr>

                            ))}

                            </tbody>

                        </table>

                    </div>

                ) : (

                    <div className="empty">

                        <MessageSquare size={30} />

                        <p>
                            No grievances found.
                        </p>

                    </div>

                )}

            </div>

            {/* MODAL */}
            {open && (

                <div className="modal-bg">

                    <form
                        className="modal grievance-modal"
                        onSubmit={submit}
                    >

                        {/* MODAL HEADER */}
                        <div className="modal-head">

                            <div>

                                <h3>
                                    Submit Grievance
                                </h3>

                                <p>
                                    Record a farmer complaint
                                    or feedback.
                                </p>

                            </div>

                            <button
                                type="button"
                                onClick={() => setOpen(false)}
                            >
                                ×
                            </button>

                        </div>

                        {/* FORM GRID */}
                        <div className="form-grid">

                            {/* MEMBER */}
                            <label>

                                Member Name

                                <input
                                    type="text"
                                    name="memberName"
                                    required
                                    placeholder="Enter member name"
                                    value={form.memberName}
                                    onChange={handleChange}
                                />

                            </label>

                            {/* CATEGORY */}
                            <label>

                                Category

                                <select
                                    name="category"
                                    value={form.category}
                                    onChange={handleChange}
                                >

                                    <option value="Payment">
                                        Payment
                                    </option>

                                    <option value="Procurement">
                                        Procurement
                                    </option>

                                    <option value="Warehouse">
                                        Warehouse
                                    </option>

                                    <option value="Sales">
                                        Sales
                                    </option>

                                    <option value="Share Capital">
                                        Share Capital
                                    </option>

                                    <option value="Dividend">
                                        Dividend
                                    </option>

                                    <option value="Other">
                                        Other
                                    </option>

                                </select>

                            </label>

                            {/* SUBJECT */}
                            <label>

                                Subject

                                <input
                                    type="text"
                                    name="subject"
                                    required
                                    placeholder="Enter subject"
                                    value={form.subject}
                                    onChange={handleChange}
                                />

                            </label>

                            {/* PRIORITY */}
                            <label>

                                Priority

                                <select
                                    name="priority"
                                    value={form.priority}
                                    onChange={handleChange}
                                >

                                    <option value="Low">
                                        Low
                                    </option>

                                    <option value="Medium">
                                        Medium
                                    </option>

                                    <option value="High">
                                        High
                                    </option>

                                    <option value="Critical">
                                        Critical
                                    </option>

                                </select>

                            </label>

                            {/* DESCRIPTION */}
                            <label className="grievance-description">

                                Description

                                <textarea
                                    name="description"
                                    required
                                    placeholder="Describe the problem..."
                                    value={form.description}
                                    onChange={handleChange}
                                />

                            </label>

                        </div>

                        {/* SUBMIT */}
                        <button
                            type="submit"
                            className="primary full"
                        >
                            Submit Grievance
                        </button>

                    </form>

                </div>

            )}

        </>
    );
}
